macro_rules! deps {
    () => {
        SolverDelegate!();
        ReplaceProjectionWith!();
        Ambiguous!();
        EvalCtxt!();
    };
}

macro_rules! predicates_for_object_candidate {
    () => {
        deps!();
        # [doc = " Assemble a list of predicates that would be present on a theoretical"] # [doc = " user impl for an object type. These predicates must be checked any time"] # [doc = " we assemble a built-in object candidate for an object type, since they"] # [doc = " are not implied by the well-formedness of the type."] # [doc = ""] # [doc = " For example, given the following traits:"] # [doc = ""] # [doc = " ```rust,ignore (theoretical code)"] # [doc = " trait Foo: Baz {"] # [doc = "     type Bar: Copy;"] # [doc = " }"] # [doc = ""] # [doc = " trait Baz {}"] # [doc = " ```"] # [doc = ""] # [doc = " For the dyn type `dyn Foo<Item = Ty>`, we can imagine there being a"] # [doc = " pair of theoretical impls:"] # [doc = ""] # [doc = " ```rust,ignore (theoretical code)"] # [doc = " impl Foo for dyn Foo<Item = Ty>"] # [doc = " where"] # [doc = "     Self: Baz,"] # [doc = "     <Self as Foo>::Bar: Copy,"] # [doc = " {"] # [doc = "     type Bar = Ty;"] # [doc = " }"] # [doc = ""] # [doc = " impl Baz for dyn Foo<Item = Ty> {}"] # [doc = " ```"] # [doc = ""] # [doc = " However, in order to make such impls non-cyclical, we need to do an"] # [doc = " additional step of eagerly folding the associated types in the where"] # [doc = " clauses of the impl. In this example, that means replacing"] # [doc = " `<Self as Foo>::Bar` with `Ty` in the first impl."] pub (in crate :: solve) fn predicates_for_object_candidate < D , I > (ecx : & mut EvalCtxt < '_ , D > , param_env : I :: ParamEnv , trait_ref : ty :: TraitRef < I > , object_bounds : I :: BoundExistentialPredicates ,) -> Result < Vec < Goal < I , I :: Predicate > > , Ambiguous > where D : SolverDelegate < Interner = I > , I : Interner , { let cx = ecx . cx () ; let mut requirements = vec ! [] ; requirements . extend (elaborate :: elaborate (cx , cx . explicit_super_predicates_of (trait_ref . def_id) . iter_instantiated (cx , trait_ref . args) . map (| (pred , _) | pred) ,)) ; for associated_type_def_id in cx . associated_type_def_ids (trait_ref . def_id . into ()) { if cx . generics_require_sized_self (associated_type_def_id) { continue ; } requirements . extend (cx . item_bounds (associated_type_def_id) . iter_instantiated (cx , trait_ref . args)) ; } let mut replace_projection_with : HashMap < _ , Vec < _ > > = HashMap :: default () ; for bound in object_bounds . iter () { if let ty :: ExistentialPredicate :: Projection (proj) = bound . skip_binder () { let proj = proj . with_self_ty (cx , trait_ref . self_ty ()) ; replace_projection_with . entry (proj . def_id ()) . or_default () . push (bound . rebind (proj)) ; } } let mut folder = ReplaceProjectionWith { ecx , param_env , self_ty : trait_ref . self_ty () , mapping : & replace_projection_with , nested : vec ! [] , } ; let requirements = requirements . try_fold_with (& mut folder) ? ; Ok (folder . nested . into_iter () . chain (requirements . into_iter () . map (| clause | Goal :: new (cx , param_env , clause))) . collect ()) }
    };
}

predicates_for_object_candidate!();